-- Load sales.FactNewBusiness (fact).
-- One stored procedure per destination table (DE Policy v2, gold code standards).
-- The SELECT comes from models/gold/sales/FactNewBusiness.sql.
-- Generated by `python -m dbde render` from models/gold/sales/FactNewBusiness.yml. Do not edit: change the spec and render again.

CREATE OR REPLACE PROCEDURE ${gold_catalog}.sales.LoadFactNewBusiness(
    RunLoadDate DATE,
    RunLoadStepID STRING
)
LANGUAGE SQL
SQL SECURITY INVOKER
COMMENT 'Loads sales.FactNewBusiness with MERGE. Generated by dbde from models/gold/sales/FactNewBusiness.yml.'
AS BEGIN
    DECLARE RunTimestamp TIMESTAMP DEFAULT current_timestamp();
    DECLARE MaxKey BIGINT DEFAULT 0;

    -- New surrogate keys continue from the highest key in use
    -- (-1 is the unknown member).
    SET MaxKey = (
        SELECT coalesce(max(FactNewBusiness_SK), 0)
        FROM ${gold_catalog}.sales.FactNewBusiness
        WHERE FactNewBusiness_SK > 0
    );

    MERGE INTO ${gold_catalog}.sales.FactNewBusiness AS target
    USING (
        WITH source_rows AS (
            with

            new_business as (

                select * from ${silver_catalog}.sales.NewBusinessPolicy

            ),

            agent as (

                select * from ${gold_catalog}.distribution.DimAgent

            )

            select
                new_business.Policy_BK,
                coalesce(agent.DimAgent_SK, -1) as DimAgent_SK,
                new_business.ProductCode,
                new_business.AnnualPremiumAmount,
                new_business.IssueDate
            from new_business
            left join agent
                on agent.Agent_BK = new_business.Agent_BK
                and new_business.IssueDate between agent.StartDate and agent.EndDate
        ),
        typed AS (
            SELECT
                CAST(source_rows.Policy_BK AS VARCHAR(20)) AS Policy_BK,
                CAST(source_rows.DimAgent_SK AS BIGINT) AS DimAgent_SK,
                CAST(source_rows.ProductCode AS VARCHAR(20)) AS ProductCode,
                CAST(source_rows.AnnualPremiumAmount AS DECIMAL(18,2)) AS AnnualPremiumAmount,
                CAST(source_rows.IssueDate AS DATE) AS IssueDate
            FROM source_rows
            WHERE source_rows.IssueDate >= date_sub(RunLoadDate, 7)
        )
        SELECT
            typed.*,
            MaxKey + row_number() OVER (ORDER BY typed.Policy_BK)
                AS NewKey
        FROM typed
    ) AS source
    ON target.Policy_BK = source.Policy_BK
    WHEN MATCHED AND (
        NOT (target.DimAgent_SK <=> source.DimAgent_SK)
        OR NOT (target.ProductCode <=> source.ProductCode)
        OR NOT (target.AnnualPremiumAmount <=> source.AnnualPremiumAmount)
        OR NOT (target.IssueDate <=> source.IssueDate)
    ) THEN UPDATE SET
        DimAgent_SK = source.DimAgent_SK,
        ProductCode = source.ProductCode,
        AnnualPremiumAmount = source.AnnualPremiumAmount,
        IssueDate = source.IssueDate,
        LastUpdateLoadStepID = RunLoadStepID,
        LastUpdateTimestamp = RunTimestamp
    WHEN NOT MATCHED THEN INSERT (
        FactNewBusiness_SK,
        Policy_BK,
        DimAgent_SK,
        ProductCode,
        AnnualPremiumAmount,
        IssueDate,
        InsertLoadStepID,
        InsertTimestamp,
        LastUpdateLoadStepID,
        LastUpdateTimestamp
    ) VALUES (
        source.NewKey,
        source.Policy_BK,
        source.DimAgent_SK,
        source.ProductCode,
        source.AnnualPremiumAmount,
        source.IssueDate,
        RunLoadStepID,
        RunTimestamp,
        RunLoadStepID,
        RunTimestamp
    );
END;
